package main

import (
	"bufio"
	"fmt"
	"os"
)

const size = 6

type Matrix [size][size]int64

func multiply(a, b Matrix, mod int64) Matrix {
	var c Matrix
	for i := 0; i < size; i++ {
		for k := 0; k < size; k++ {
			if a[i][k] == 0 {
				continue
			}
			for j := 0; j < size; j++ {
				c[i][j] = (c[i][j] + a[i][k]*b[k][j]) % mod
			}
		}
	}
	return c
}

func power(a Matrix, exp int64, mod int64) Matrix {
	var result Matrix
	for i := 0; i < size; i++ {
		result[i][i] = 1 % mod
	}
	for exp > 0 {
		if exp&1 == 1 {
			result = multiply(result, a, mod)
		}
		a = multiply(a, a, mod)
		exp >>= 1
	}
	return result
}

func normalize(x, mod int64) int64 {
	x %= mod
	if x < 0 {
		x += mod
	}
	return x
}

func main() {
	in := bufio.NewReader(os.Stdin)

	var n, sx, sy, dx, dy, t int64
	fmt.Fscan(in, &n, &sx, &sy, &dx, &dy, &t)

	if n == 1 {
		fmt.Println("1 1")
		return
	}

	var transition Matrix

	transition[0] = [size]int64{2, 1, 1, 0, 1, 2}
	transition[1] = [size]int64{1, 2, 0, 1, 1, 2}
	transition[2] = [size]int64{1, 1, 1, 0, 1, 2}
	transition[3] = [size]int64{1, 1, 0, 1, 1, 2}
	transition[4] = [size]int64{0, 0, 0, 0, 1, 1}
	transition[5] = [size]int64{0, 0, 0, 0, 0, 1}

	for i := 0; i < size; i++ {
		for j := 0; j < size; j++ {
			transition[i][j] %= n
		}
	}

	state := [size]int64{
		(sx - 1) % n,
		(sy - 1) % n,
		normalize(dx, n),
		normalize(dy, n),
		0,
		1,
	}

	result := power(transition, t, n)

	var final [size]int64
	for i := 0; i < size; i++ {
		for j := 0; j < size; j++ {
			final[i] = (final[i] + result[i][j]*state[j]) % n
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, final[0]+1, final[1]+1)
}
